const CLAIMS_SAUDE = /(antes\s+e\s+depois|\bperd(a|e|er)\s+(até\s+)?\d+\s*(kg|quilos)|\bemagre[cç]a\s+\d|\bcura(r|do|da)?\b|resultado\s+garantido|últimas\s+vagas)/i;

